-- Incluído pelo harness PostgreSQL descartável dentro de uma transação revertida.
do $$ declare
 ids uuid[] := array['40000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002']::uuid[];
 changes jsonb := '[{"id":"40000000-0000-0000-0000-000000000001","nova_data":"2099-11-28"},{"id":"40000000-0000-0000-0000-000000000002","nova_data":"2099-11-28"}]';
 expected jsonb := '[{"id":"40000000-0000-0000-0000-000000000001"},{"id":"40000000-0000-0000-0000-000000000002"}]';
 p jsonb; r jsonb; before_data jsonb; after_data jsonb;
begin
 select jsonb_agg(to_jsonb(a)-'data' order by id) into before_data from public.aulas a where id=any(ids);
 p := public.reagendar_aulas_turma(changes,expected,false);
 perform pg_temp.assert_ok(not (p->>'applied')::boolean and p->'conflicts'='[]','prévia de reagendamento sem escrita');
 perform pg_temp.assert_ok((select count(*)=2 from public.aulas where id=any(ids) and data='2099-11-14'),'prévia não muda data');
 r := public.reagendar_aulas_turma(changes,p->'snapshot',true);
 perform pg_temp.assert_ok((r->>'applied')::boolean and (select count(*)=2 from public.aulas where id=any(ids) and data='2099-11-28'),'reagendamento confirmado');
 select jsonb_agg(to_jsonb(a)-'data' order by id) into after_data from public.aulas a where id=any(ids);
 perform pg_temp.assert_ok(before_data=after_data,'preserva todos os campos exceto a data');
 perform pg_temp.assert_ok((select count(*)=1 from public.audit_logs where details->>'type'='TURMA_RESCHEDULE'),'audita reagendamento');
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,true)',changes,p->'snapshot'),'novas datas');
 update public.aulas set data='2099-11-14' where id=any(ids);
 p := public.reagendar_aulas_turma(changes,expected,false);
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,true)',replace(changes::text,'2099-11-28','2099-11-29'),p->'snapshot'),'datas foram alteradas');
 update public.aulas set sala='Mudou' where id=ids[2];
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,true)',changes,p->'snapshot'),'datas foram alteradas');
 update public.aulas set sala='Sala 4' where id=ids[2];
 -- Revalida novas ocupações depois da prévia, inclusive outra aula da própria turma.
 insert into public.aulas select '40000000-0000-0000-0000-000000000009',tenant_id,turma_id,numero_turma,curso_id,null,null,instrutor_id,'Sala 4','2099-11-28','08:30','09:30','agendada',2,nome_curso from public.aulas where id=ids[1];
 r := public.reagendar_aulas_turma(changes,p->'snapshot',true);
 perform pg_temp.assert_ok(not (r->>'applied')::boolean and jsonb_array_length(r->'conflicts')>0,'nova ocupação bloqueia todo o lote');
 perform pg_temp.assert_ok((select count(*)=2 from public.aulas where id=any(ids) and data='2099-11-14'),'conflito não deixa metade do lote');
 delete from public.aulas where id='40000000-0000-0000-0000-000000000009';
 insert into public.events values ('70000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',null,'Férias','2099-11-28','00:00','00:00','ferias','agendado');
 p := public.reagendar_aulas_turma(changes,expected,false);
 perform pg_temp.assert_ok(jsonb_array_length(p->'conflicts')=1,'férias no destino');
 delete from public.events;
 insert into public.feriados values('80000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','2099-11-28','Feriado',true);
 p := public.reagendar_aulas_turma(changes,expected,false);
 perform pg_temp.assert_ok(jsonb_array_length(p->'conflicts')=1,'feriado no destino');
 delete from public.feriados;
 insert into public.datas_bloqueadas values('80000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001','2099-11-28','Recesso',true);
 p := public.reagendar_aulas_turma(changes,expected,false);
 perform pg_temp.assert_ok(jsonb_array_length(p->'conflicts')=1,'recesso no destino');
 delete from public.datas_bloqueadas;
 update public.aulas set data='2099-11-15',horario_inicio='08:30' where id=ids[2];
 p := public.reagendar_aulas_turma(changes,expected,false);
 perform pg_temp.assert_ok(jsonb_array_length(p->'conflicts')=1,'não sobrepõe dias diferentes selecionados');
 update public.aulas set data='2099-11-14',horario_inicio='10:00' where id=ids[2];
 -- Troca de datas entre duas aulas: considera as posições finais, não as antigas.
 update public.aulas set data='2099-11-28' where id=ids[2];
 p := public.reagendar_aulas_turma(jsonb_set(changes,'{1,nova_data}','"2099-11-14"'),expected,false);
 perform pg_temp.assert_ok(p->'conflicts'='[]','permite permutar datas livres ao final');
 update public.aulas set data='2099-11-14' where id=ids[2];
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',jsonb_set(changes,'{1,nova_data}','"2099-11-29"'),expected),'mesmo dia');
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',replace(changes::text,'2099-11-28','2020-01-01'),expected),'novas datas futuras');
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',replace(changes::text,'2099-11-28','2099-02-30'),expected),'datas válidas');
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',jsonb_build_array(changes->0,changes->0),expected),'repetidas');
 update public.aulas set status='concluida' where id=ids[1];
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',changes,expected),'concluídas no passado');
 update public.aulas set status='agendada',data='2020-01-01' where id=ids[1];
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',changes,expected),'justificativa');
 update public.aulas set data='2020-01-01' where id=any(ids);
 p := public.reagendar_aulas_turma(changes,expected,false,'Aula adiada; agenda não foi atualizada.');
 perform pg_temp.assert_ok(not (p->>'applied')::boolean,'prévia de aula passada agendada sem escrita');
 r := public.reagendar_aulas_turma(changes,p->'snapshot',true,'Aula adiada; agenda não foi atualizada.');
 perform pg_temp.assert_ok((r->>'applied')::boolean and (select count(*)=2 from public.aulas where id=any(ids) and status='agendada' and data='2099-11-28'),'corrige aula passada agendada');
 update public.aulas set data='2020-01-01',status='concluida' where id=any(ids);
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',changes,expected),'justificativa');
 p := public.reagendar_aulas_turma(changes,expected,false,'Aula não ocorreu; corrigindo conclusão automática.');
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,true,%L)',changes,p->'snapshot','Outra justificativa diferente da prévia.'),'datas foram alteradas');
 r := public.reagendar_aulas_turma(changes,p->'snapshot',true,'Aula não ocorreu; corrigindo conclusão automática.');
 perform pg_temp.assert_ok((r->>'applied')::boolean and (select count(*)=2 from public.aulas where id=any(ids) and status='agendada' and data='2099-11-28'),'reabre concluída passada na nova data');
 perform pg_temp.assert_ok(exists(select 1 from public.audit_logs where details->>'motivo'='Aula não ocorreu; corrigindo conclusão automática.' and details->'before'->0->>'status'='concluida'),'preserva status anterior e motivo na auditoria');
 update public.aulas set data='2099-11-14' where id=any(ids);
 update public.aulas set status='em_andamento' where id=ids[1];
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false,%L)',changes,expected,'Correção administrativa justificada.'),'em andamento');
 update public.aulas set status='cancelada' where id=ids[1];
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false,%L)',changes,expected,'Correção administrativa justificada.'),'canceladas');
 update public.aulas set status='agendada' where id=ids[1];
 update public.aulas set data='2099-11-14' where id=ids[1];
 perform pg_temp.expect_failure($q$select public.reagendar_aulas_turma('[{"id":"40000000-0000-0000-0000-000000000001","nova_data":"2099-11-28"},{"id":"40000000-0000-0000-0000-000000000003","nova_data":"2099-11-28"}]','[{"id":"40000000-0000-0000-0000-000000000001"},{"id":"40000000-0000-0000-0000-000000000003"}]',false)$q$,'única turma');
 update public.aulas set status='agendada',turma_id=null,curso_id=null,numero_turma='706254',nome_curso='Curso legado' where id=any(ids);
 p := public.reagendar_aulas_turma(changes,expected,false);
 r := public.reagendar_aulas_turma(changes,p->'snapshot',true);
 perform pg_temp.assert_ok((r->>'applied')::boolean,'reagenda turmas legadas sem IDs');
 update public.aulas set data='2099-11-14',turma_id='50000000-0000-0000-0000-000000000001',curso_id='30000000-0000-0000-0000-000000000001',numero_turma='703601',nome_curso=null where id=any(ids);
 perform set_config('test.user_id','00000000-0000-0000-0000-000000000002',true);
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',changes,expected),'não tem permissão');
 perform set_config('test.user_id','00000000-0000-0000-0000-000000000003',true);
 perform pg_temp.expect_failure(format('select public.reagendar_aulas_turma(%L,%L,false)',changes,expected),'não tem permissão');
 perform set_config('test.user_id','00000000-0000-0000-0000-000000000001',true);
 perform pg_temp.expect_failure($q$select public.reagendar_aulas_turma('[{"id":"40000000-0000-0000-0000-000000000004","nova_data":"2099-11-28"}]','[{"id":"40000000-0000-0000-0000-000000000004"}]',false)$q$,'não está mais disponível');
end $$;
